.cabinet-secretaries {
    width: 100%;
    max-width: 1200px;
    margin: 30px auto;
    font-family: Arial, Helvetica, sans-serif;
    color: #222;
}

.cabinet-secretaries-title {
    margin: 0 0 20px 0;
    font-size: 28px;
    line-height: 1.3;
    font-weight: 700;
    text-align: center;
}

/* Table container */
.cabinet-table-wrapper {
    width: 100%;
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
}

/* Desktop table */
.cabinet-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
    background: #fff;
    font-size: 15px;
}

/* Column widths */
.cabinet-table th:nth-child(1),
.cabinet-table td:nth-child(1) {
    width: 50%;
}

.cabinet-table th:nth-child(2),
.cabinet-table td:nth-child(2),
.cabinet-table th:nth-child(3),
.cabinet-table td:nth-child(3) {
    width: 25%;
}

/* Header */
.cabinet-table thead th {
    background: #A3BBF3;
    color: #000;
    border: 1px solid #ced4da;
    padding: 14px 16px;
    text-align: center;
    font-weight: 700;
    vertical-align: middle;
}

/* Cells */
.cabinet-table tbody td {
    border: 1px solid #dee2e6;
    padding: 13px 16px;
    vertical-align: middle;
    line-height: 1.5;
}

/* Name column */
.cabinet-table tbody td:first-child {
    font-weight: 600;
}

/* Date columns */
.cabinet-table tbody td:nth-child(2),
.cabinet-table tbody td:nth-child(3) {
    text-align: center;
    white-space: nowrap;
}

/* Alternate rows */
.cabinet-table tbody tr:nth-child(even) {
    background: #f8f9fa;
}

/* Hover */
.cabinet-table tbody tr:hover {
    background: #eef8fb;
}


/* =========================================================
   TABLET
   ========================================================= */

@media (max-width: 768px) {

    .cabinet-secretaries {
        margin: 20px auto;
    }

    .cabinet-secretaries-title {
        font-size: 23px;
        margin-bottom: 15px;
    }

    .cabinet-table {
        font-size: 14px;
    }

    .cabinet-table thead th,
    .cabinet-table tbody td {
        padding: 11px 12px;
    }
}


/* =========================================================
   MOBILE CARD VIEW
   ========================================================= */

@media (max-width: 600px) {

    .cabinet-secretaries {
        width: 100%;
        margin: 15px auto;
    }

    .cabinet-secretaries-title {
        font-size: 21px;
        margin-bottom: 16px;
    }

    /*
       Hide normal table header
    */
    .cabinet-table thead {
        display: none;
    }

    /*
       Convert table to block layout
    */
    .cabinet-table,
    .cabinet-table tbody,
    .cabinet-table tr,
    .cabinet-table td {
        display: block;
        width: 100%;
        box-sizing: border-box;
    }

    .cabinet-table {
        border: 0;
        background: transparent;
        table-layout: auto;
        font-size: 14px;
    }

    /*
       Each Secretary becomes a card
    */
    .cabinet-table tbody tr {
        margin-bottom: 16px;
        background: #fff;
        border: 1px solid #d9dee2;
        border-radius: 10px;
        overflow: hidden;
        box-shadow: 0 2px 8px rgba(0, 0, 0, 0.06);
    }

    /*
       Remove desktop borders
    */
    .cabinet-table tbody td {
        width: 100% !important;
        border: 0;
        border-bottom: 1px solid #eeeeee;
        padding: 11px 14px;
        text-align: left !important;
        white-space: normal !important;
    }

    .cabinet-table tbody td:last-child {
        border-bottom: 0;
    }

    /*
       Labels
    */
    .cabinet-table tbody td::before {
        display: block;
        margin-bottom: 4px;
        font-size: 11px;
        line-height: 1.3;
        font-weight: 700;
        color: #666;
        text-transform: uppercase;
        letter-spacing: 0.4px;
    }

    .cabinet-table tbody td:nth-child(1)::before {
        content: "Cabinet Secretary";
    }

    .cabinet-table tbody td:nth-child(2)::before {
        content: "From";
    }

    .cabinet-table tbody td:nth-child(3)::before {
        content: "To";
    }

    /*
       Secretary name gets stronger visual emphasis
    */
    .cabinet-table tbody td:nth-child(1) {
        background: #f1f8fa;
        color: #222;
        font-size: 15px;
        font-weight: 700;
    }

    /*
       Dates
    */
    .cabinet-table tbody td:nth-child(2),
    .cabinet-table tbody td:nth-child(3) {
        text-align: left !important;
        font-size: 14px;
    }

}


/* =========================================================
   VERY SMALL MOBILE
   ========================================================= */

@media (max-width: 400px) {

    .cabinet-secretaries-title {
        font-size: 19px;
    }

    .cabinet-table {
        font-size: 13px;
    }

    .cabinet-table tbody td {
        padding: 10px 12px;
    }

    .cabinet-table tbody td:nth-child(1) {
        font-size: 14px;
    }

    .cabinet-table tbody td::before {
        font-size: 10px;
    }
}

.rti-table-wrapper {
