.document-table-wrapper {
    width: 100%;
    margin: 30px 0;
}

.document-table {
    width: 100%;
    border-collapse: collapse;
    background: #fff;
    font-size: 15px;
    line-height: 1.5;
}

.document-table th,
.document-table td {
    border: 1px solid #dee2e6;
    padding: 12px 14px;
    vertical-align: top;
}

.document-table thead th {
    background: #1a889e;
    color: #000;
    text-align: center;
    font-weight: 600;
    vertical-align: middle;
}

.document-table tbody tr:nth-child(even) {
    background: #f8f9fa;
}

.document-table tbody tr:hover {
    background: #eef7fa;
}

.document-table td:first-child {
    text-align: center;
    white-space: nowrap;
    width: 70px;
}

.document-table a {
    color: #0056b3;
    text-decoration: underline;
    overflow-wrap: anywhere;
    word-break: break-word;
}


/* ================================
   MOBILE
   ================================ */

@media (max-width: 768px) {

    .document-table-wrapper {
        width: 100%;
        margin: 20px 0;
    }

    /* Hide desktop table header */
    .document-table thead {
        display: none;
    }

    /* Remove table structure */
    .document-table,
    .document-table tbody,
    .document-table tr,
    .document-table td {
        display: block;
        width: 100%;
    }

    .document-table {
        border: 0;
        background: transparent;
        font-size: 14px;
    }

    /* Each row becomes a card */
    .document-table tbody tr {
        margin-bottom: 18px;
        background: #fff;
        border: 1px solid #dfe3e6;
        border-radius: 10px;
        overflow: hidden;
        box-shadow: 0 2px 8px rgba(0, 0, 0, 0.06);
    }

    .document-table tbody tr:nth-child(even) {
        background: #fff;
    }

    .document-table tbody tr:hover {
        background: #fff;
    }

    /* Individual cells */
    .document-table td {
        border: 0;
        border-bottom: 1px solid #eeeeee;
        padding: 12px 14px 12px 14px;
        text-align: left !important;
        min-height: 44px;
        box-sizing: border-box;
    }

    .document-table td:last-child {
        border-bottom: 0;
    }

    /* Labels before each value */
    .document-table td:nth-child(1)::before {
        content: "Sl. No.";
    }

    .document-table td:nth-child(2)::before {
        content: "Category";
    }

    .document-table td:nth-child(3)::before {
        content: "Document";
    }

    .document-table td:nth-child(4)::before {
        content: "Procedure to obtain";
    }

    .document-table td:nth-child(5)::before {
        content: "Held by / Under the control of";
    }

    .document-table td::before {
        display: block;
        font-size: 12px;
        font-weight: 700;
        color: #555;
        margin-bottom: 5px;
        text-transform: uppercase;
        letter-spacing: 0.3px;
    }

    /* Serial number styling */
    .document-table td:first-child {
        background: #f1f8fa;
        font-weight: 700;
        color: #333;
    }

    /* Links */
    .document-table a {
        display: inline-block;
        max-width: 100%;
        font-size: 13px;
        line-height: 1.5;
        overflow-wrap: anywhere;
        word-break: break-word;
    }

}


/* ================================
   SMALL MOBILE
   ================================ */

@media (max-width: 480px) {

    .document-table-wrapper {
        margin: 15px 0;
    }

    .document-table {
        font-size: 13px;
    }

    .document-table tbody tr {
        border-radius: 8px;
        margin-bottom: 15px;
    }

    .document-table td {
        padding: 10px 12px;
    }

    .document-table td::before {
        font-size: 11px;
        margin-bottom: 4px;
    }

    .document-table a {
        font-size: 12px;
    }
}

