* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
}

body {
    background-color: #fcfcfc; /* Light background as seen in image */
    display: flex;
    justify-content: center;
    padding: 40px 20px;
}

.container {
    width: 100%;
    max-width: 900px;
}
/* Links Wrapper */
.links-wrapper {
    display: flex;
    flex-direction: column;
    gap: 12px; /* Spacing between cards */
}

/* Individual Link Card */
.link-card {
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 10px 15px;
    transition: box-shadow 0.3s ease;
}

.link-card:hover {
    box-shadow: 0 2px 8px rgba(0,0,0,0.05);
}

.link-text {
    font-size: 16px;
    color: #333;
    font-weight: 500;
}

/* Visit Website Button */
.visit-btn {
    background-color: #dbe4ff; /* Very light blue background */
    color: #2c54c1; /* Strong blue text */
    text-decoration: none;
    font-size: 12px;
    font-weight: bold;
    padding: 10px 20px;
    border-radius: 6px;
    display: flex;
    align-items: center;
    gap: 8px;
    transition: background 0.3s ease;
}

.visit-btn:hover {
    background-color: #c9d6ff;
}

.visit-btn i {
    font-size: 14px;
}

/* Responsive adjustment */
@media (max-width: 600px) {
    .link-card {
        flex-direction: column;
        align-items: flex-start;
        gap: 10px;
    }
    .visit-btn {
        width: 100%;
        justify-content: center;
    }
}

/* =========================================================
   HELP PAGE
   Responsive: Desktop / Tablet / Mobile
   ========================================================= */

.help-page {
    width: 100%;
    max-width: 1100px;
    margin: 0 auto;
    padding: 30px 20px 50px;
    font-family: "Noto Sans", Arial, sans-serif;
    color: #222;
    box-sizing: border-box;
}

.help-page *,
.help-page *::before,
.help-page *::after {
    box-sizing: border-box;
}


/* =========================================================
   HEADINGS
   ========================================================= */

.help-page h1 {
    margin: 0 0 25px;
    font-size: 36px;
    line-height: 1.3;
    font-weight: 700;
    color: #111;
}

.help-page h2 {
    margin: 30px 0 12px;
    font-size: 24px;
    line-height: 1.4;
    font-weight: 600;
    color: #2b5dab;
}

.help-page h3 {
    margin: 25px 0 12px;
    font-size: 20px;
    line-height: 1.4;
    font-weight: 600;
    color: #111;
}


/* =========================================================
   PARAGRAPHS
   ========================================================= */

.help-page p,
.help-page .text {
    margin: 0 0 16px;
    font-size: 16px;
    line-height: 1.75;
    font-weight: 400;
    color: #222;
    text-align: justify;
}


/* =========================================================
   LINKS
   ========================================================= */

.help-page a {
    color: #1a5fd0;
    font-size: 16px;
    line-height: 1.6;
    text-decoration: underline;
    text-underline-offset: 2px;
    overflow-wrap: anywhere;
    word-break: break-word;
}

.help-page a:hover {
    text-decoration-thickness: 2px;
}


/* =========================================================
   TABLE WRAPPER
   ========================================================= */

.help-table-wrapper {
    width: 100%;
    max-width: 100%;
    margin: 20px 0 30px;
}


/* =========================================================
   COMMON TABLE
   BOTH TABLES USE EXACTLY THE SAME DESIGN
   ========================================================= */

.help-table {
    width: 100%;
    border-collapse: collapse;
    border-spacing: 0;
    margin: 0;
    background: #fff;
}


/* =========================================================
   TABLE HEADER + CELLS
   ========================================================= */

.help-table th,
.help-table td {
    border: 1px solid #d1d5db;
    padding: 12px 14px;
    text-align: left;
    vertical-align: top;
    font-size: 16px;
    line-height: 1.6;
    overflow-wrap: anywhere;
    word-break: break-word;
}

.help-table th {
    background: #f2f2f2;
    color: #111;
    font-weight: 700;
    vertical-align: middle;
}

.help-table td {
    color: #222;
}


/* =========================================================
   FIRST TABLE COLUMN WIDTH
   ========================================================= */

.help-table--formats th:nth-child(1),
.help-table--formats td:nth-child(1) {
    width: 35%;
}

.help-table--formats th:nth-child(2),
.help-table--formats td:nth-child(2) {
    width: 65%;
}


/* =========================================================
   SECOND TABLE COLUMN WIDTH
   ========================================================= */

.help-table--readers th:nth-child(1),
.help-table--readers td:nth-child(1) {
    width: 40%;
}

.help-table--readers th:nth-child(2),
.help-table--readers td:nth-child(2) {
    width: 40%;
}

.help-table--readers th:nth-child(3),
.help-table--readers td:nth-child(3) {
    width: 20%;
}


/* =========================================================
   TABLET
   ========================================================= */

@media (max-width: 900px) {

    .help-page {
        padding: 25px 18px 40px;
    }

    .help-page h1 {
        font-size: 32px;
    }

    .help-page h2 {
        font-size: 22px;
    }

    .help-page h3 {
        font-size: 19px;
    }

    .help-table th,
    .help-table td {
        padding: 11px 12px;
    }
}


/* =========================================================
   MOBILE
   BOTH TABLES BECOME THE SAME CARD DESIGN
   ========================================================= */

@media (max-width: 768px) {

    .help-page {
        width: 100%;
        max-width: 100%;
        padding: 20px 15px 35px;
    }


    /* -------------------------
       Headings
       ------------------------- */

    .help-page h1 {
        font-size: 26px;
        margin-bottom: 20px;
    }

    .help-page h2 {
        font-size: 21px;
        margin-top: 25px;
    }

    .help-page h3 {
        font-size: 18px;
        margin-top: 22px;
    }


    /* -------------------------
       Paragraphs
       ------------------------- */

    .help-page p,
    .help-page .text {
        font-size: 16px;
        line-height: 1.7;
        text-align: justify;
    }


    /* -------------------------
       Table
       ------------------------- */

    .help-table-wrapper {
        width: 100%;
        margin: 18px 0 25px;
    }

    .help-table {
        display: block;
        width: 100%;
        border: 0;
    }

    .help-table thead {
        display: none;
    }

    .help-table tbody {
        display: block;
        width: 100%;
    }


    /* -------------------------
       Each TR becomes a card
       ------------------------- */

    .help-table tr {
        display: block;
        width: 100%;
        margin-bottom: 16px;
        border: 1px solid #d1d5db;
        border-radius: 6px;
        background: #fff;
        overflow: hidden;
    }


    /* -------------------------
       Each TD becomes a row
       ------------------------- */

    .help-table td {
        display: block;
        width: 100% !important;
        min-height: 0;

        position: relative;

        padding: 10px 12px 10px 145px;

        border: 0;
        border-bottom: 1px solid #e5e7eb;

        font-size: 16px;
        line-height: 1.55;

        overflow-wrap: anywhere;
        word-break: break-word;
    }

    .help-table td:last-child {
        border-bottom: 0;
    }


    /* -------------------------
       Mobile labels
       ------------------------- */

    .help-table td::before {
        position: absolute;
        left: 12px;
        top: 10px;

        width: 120px;
        padding-right: 8px;

        font-size: 14px;
        line-height: 1.4;
        font-weight: 700;

        color: #333;
    }


    /* -------------------------
       FIRST TABLE LABELS
       ------------------------- */

    .help-table--formats td:nth-child(1)::before {
        content: "Document Type";
    }

    .help-table--formats td:nth-child(2)::before {
        content: "Plug-in / Download";
    }


    /* -------------------------
       SECOND TABLE LABELS
       ------------------------- */

    .help-table--readers td:nth-child(1)::before {
        content: "Screen Reader";
    }

    .help-table--readers td:nth-child(2)::before {
        content: "Website";
    }

    .help-table--readers td:nth-child(3)::before {
        content: "Type";
    }


    /* -------------------------
       Links
       ------------------------- */

    .help-table a {
        font-size: 16px;
    }
}


/* =========================================================
   SMALL MOBILE
   ========================================================= */

@media (max-width: 480px) {

    .help-page {
        padding: 18px 12px 30px;
    }

    .help-page h1 {
        font-size: 24px;
    }

    .help-page h2 {
        font-size: 20px;
    }

    .help-page h3 {
        font-size: 18px;
    }

    .help-page p,
    .help-page .text {
        font-size: 16px;
        line-height: 1.65;
        text-align: justify;
    }

    .help-table td {
        padding: 10px 10px 10px 120px;
        font-size: 16px;
    }

    .help-table td::before {
        left: 10px;
        width: 100px;
        font-size: 13px;
    }
}


/* =========================================================
   VERY SMALL MOBILE
   At 360px and below, labels move ABOVE content
   ========================================================= */

@media (max-width: 360px) {

    .help-page {
        padding-left: 10px;
        padding-right: 10px;
    }

    .help-page h1 {
        font-size: 23px;
    }

    .help-page h2 {
        font-size: 19px;
    }

    .help-page h3 {
        font-size: 17px;
    }


    .help-table td {
        padding: 10px;
        font-size: 16px;
    }

    .help-table td::before {
        position: static;
        display: block;

        width: 100%;
        margin-bottom: 4px;
        padding: 0;

        font-size: 14px;
    }
}

